// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(address caller, address to, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(to != address(0));
        vm.assume(caller != address(c));
        vm.assume(amount > 0);
        vm.deal(caller, amount);
        vm.prank(caller);
        c.deposit{value: amount}();
        vm.prank(caller);
        bool ok;
        try c.migrateTo(to) { ok = true; } catch { ok = false; }
        assertTrue(caller == address(0) || !ok);
    }
}
